import json
d=json.load(open('/tmp/full.json'))
for t in d['data']['__schema']['types']:
    for f in (t.get('fields') or []):
        if f['name'].lower()=='app':
            print('FIELD app on', t['name'])
    for f in (t.get('inputFields') or []):
        if f['name'].lower()=='app':
            print('INPUT app on', t['name'])
"

