import json
d=json.load(open('/tmp/muts.json'))
for f in d['data']['__schema']['mutationType']['fields']:
    for a in f['args']:
        t=a['type']
        name = t.get('name') or (t.get('ofType') or {}).get('name')
        if name and ('App' in name or 'app' in name):
            print(f['name'],'->',a['name'], name, t.get('kind'))
"

